    // 通用 data-tooltip 提示：页面任意元素标记 data-tooltip="内容" 即可
    (function initTooltip() {
        var $tip = null;
        var $arrow = null;
        $(document).on('mouseenter', '[data-tooltip]', function() {
            var text = $(this).attr('data-tooltip');
            if (!text) return;
            // tooltip 主体
            $tip = $('<div>' + text + '</div>').css({
                position: 'absolute',
                background: '#383838',
                color: '#fff',
                padding: '6px 10px',
                borderRadius: '5px',
                fontSize: '12px',
                lineHeight: '18px',
                maxWidth: '250px',
                boxShadow: '4px 4px 8px rgba(0,0,0,0.3)',
                zIndex: 9999,
                pointerEvents: 'none'
            }).appendTo('body');
            // 底部小三角
            $arrow = $('<div></div>').css({
                position: 'absolute',
                width: 0,
                height: 0,
                borderLeft: '6px solid transparent',
                borderRight: '6px solid transparent',
                borderTop: '6px solid #383838',
                pointerEvents: 'none',
                zIndex: 9999
            }).appendTo('body');

            // 兼容 IE 的滚动位置获取
            var scrollX = window.pageXOffset || document.documentElement.scrollLeft || 0;
            var scrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
            var rect = this.getBoundingClientRect();
            var tipW = $tip.outerWidth();
            var tipH = $tip.outerHeight();
            var centerX = rect.left + rect.width / 2 + scrollX;
            // tooltip 在上方
            var left = centerX - tipW / 2;
            var top = rect.top - tipH - 8 + scrollY;
            // 右侧溢出修正
            if (left + tipW > $(window).width() + scrollX) {
                left = $(window).width() + scrollX - tipW - 4;
            }
            // 左侧溢出修正
            if (left < scrollX) { left = scrollX + 4; }
            $tip.css({ left: left, top: top });
            // 三角居中指向图标
            $arrow.css({
                left: centerX - 6,
                top: rect.top - 8 + scrollY
            });
        }).on('mouseleave', '[data-tooltip]', function() {
            if ($tip) { $tip.remove(); $tip = null; }
            if ($arrow) { $arrow.remove(); $arrow = null; }
        });
    })();
});
